'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';
import { Drawer } from '../drawer/Drawer';

export type SiteNavItem = {
  href: string;
  label: string;
  /** Render with target=_blank + rel=noopener. */
  external?: boolean;
};

export type SiteHeaderProps = React.HTMLAttributes<HTMLElement> & {
  /** Brand slot — logo/lockup or wordmark. Wrapped in a link to "/". */
  brand: React.ReactNode;
  /** Primary navigation items. */
  items: SiteNavItem[];
  /** Current route for active styling (aria-current="page"). */
  activeHref?: string;
  /**
   * Active matching: 'prefix' highlights /docs when on /docs/installation
   * (default — marketing), 'exact' only the identical href (app chrome).
   */
  match?: 'prefix' | 'exact';
  /** Right-aligned actions (theme toggle, GitHub, CTA). */
  actions?: React.ReactNode;
  /** Custom link element for routers (Next Link, react-router Link). */
  linkComponent?: React.ElementType;
  /** Pin to the top (default true). */
  sticky?: boolean;
  /** Title of the mobile navigation drawer. Default 'Menu'. */
  mobileLabel?: string;
};

function isActive(itemHref: string, activeHref: string | undefined, match: 'prefix' | 'exact'): boolean {
  if (!activeHref) return false;
  if (itemHref === activeHref) return true;
  if (match === 'exact') return false;
  // Prefix match on path boundaries: /docs matches /docs/components, not /docsx.
  return activeHref === itemHref || activeHref.startsWith(itemHref.endsWith('/') ? itemHref : `${itemHref}/`);
}

/**
 * Marketing/site header: sticky bar with brand, horizontal navigation with
 * prefix-aware active states, right-aligned actions and a mobile drawer.
 * Router-agnostic through `linkComponent`.
 */
export function SiteHeader({
  brand,
  items,
  activeHref,
  match = 'prefix',
  actions,
  linkComponent,
  sticky = true,
  mobileLabel = 'Menu',
  className,
  ...props
}: SiteHeaderProps) {
  const [mobileOpen, setMobileOpen] = React.useState(false);
  const Link = linkComponent ?? 'a';

  const navLink = (item: SiteNavItem, extra?: string) => {
    const active = isActive(item.href, activeHref, match);
    return (
      <Link
        key={item.href}
        href={item.href}
        aria-current={active ? 'page' : undefined}
        {...(item.external ? { target: '_blank', rel: 'noopener noreferrer' } : {})}
        onClick={extra === 'mobile' ? () => setMobileOpen(false) : undefined}
        className={cn(
          'rounded-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          extra === 'mobile'
            ? 'block rounded-md px-3 py-2 text-base hover:bg-accent'
            : 'text-sm hover:text-foreground',
          active ? 'font-medium text-foreground' : 'text-muted-foreground'
        )}
      >
        {item.label}
      </Link>
    );
  };

  return (
    <>
      <header
        className={cn(
          'w-full border-b border-border bg-background/80 backdrop-blur supports-[backdrop-filter]:bg-background/60',
          sticky && 'sticky top-0 z-40',
          className
        )}
        {...props}
      >
        <nav className="mx-auto flex h-14 w-full max-w-7xl items-center justify-between gap-4 px-4 sm:px-6">
          <div className="flex min-w-0 items-center gap-6">
            <Link href="/" aria-label="Home" className="flex shrink-0 items-center">
              {brand}
            </Link>
            <div className="hidden items-center gap-5 md:flex">{items.map((item) => navLink(item))}</div>
          </div>
          <div className="flex items-center gap-2">
            {actions}
            <button
              type="button"
              onClick={() => setMobileOpen(true)}
              aria-label="Open menu"
              className="rounded-md border border-border p-2 text-muted-foreground hover:bg-muted md:hidden"
            >
              <span aria-hidden="true">☰</span>
            </button>
          </div>
        </nav>
      </header>
      <Drawer open={mobileOpen} onOpenChange={setMobileOpen} title={mobileLabel} side="right" size="sm" animate>
        <nav aria-label="Mobile" className="flex flex-col gap-1">
          {items.map((item) => navLink(item, 'mobile'))}
        </nav>
        {actions && <div className="mt-4 border-t border-border pt-4">{actions}</div>}
      </Drawer>
    </>
  );
}

{
  "id": "site-header",
  "name": "SiteHeader",
  "tier": "organism",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "site-header",
  "exportName": "SiteHeader",
  "description": "Marketing/site header: sticky bar with brand, horizontal navigation with prefix-aware active states, right-aligned actions and a mobile drawer.",
  "designIntent": "Marketing sites repeat brand/nav/actions/mobile-menu wiring with custom active matching. SiteHeader standardizes the bar, handles /docs matching /docs/components, and stays router-agnostic via linkComponent.",
  "props": [
    {
      "name": "brand",
      "type": "ReactNode",
      "required": true,
      "description": "Brand slot (logo/lockup), wrapped in a link to /."
    },
    {
      "name": "items",
      "type": "SiteNavItem[]",
      "required": true,
      "description": "Primary nav: { href, label, external? }."
    },
    {
      "name": "activeHref",
      "type": "string",
      "required": false,
      "description": "Current route for active styling (aria-current=page)."
    },
    {
      "name": "match",
      "type": "'prefix' | 'exact'",
      "required": false,
      "defaultValue": "prefix",
      "description": "Prefix highlights parents of the current route; exact only identical hrefs.",
      "enum": [
        "prefix",
        "exact"
      ]
    },
    {
      "name": "actions",
      "type": "ReactNode",
      "required": false,
      "description": "Right-aligned actions (theme toggle, GitHub, CTA)."
    },
    {
      "name": "linkComponent",
      "type": "React.ElementType",
      "required": false,
      "description": "Router link element."
    },
    {
      "name": "sticky",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Pin the bar to the top."
    },
    {
      "name": "mobileLabel",
      "type": "string",
      "required": false,
      "defaultValue": "Menu",
      "description": "Title of the mobile navigation drawer."
    }
  ],
  "examples": [
    {
      "title": "Marketing header",
      "code": "<SiteHeader\n  brand={<img src=\"/logo.svg\" alt=\"Acme\" className=\"h-8\" />}\n  items={[{ href: '/docs', label: 'Docs' }, { href: '/pricing', label: 'Pricing' }]}\n  activeHref={pathname}\n  linkComponent={RouterLink}\n  actions={<ThemeToggle />}\n/>",
      "description": "Prefix-active nav with a mobile drawer."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use it for admin rails",
      "explanation": "Vertical app navigation belongs in Sidebar + AppShell.",
      "example": "// Avoid\n<SiteHeader items={adminNav} />\n\n// Prefer\n<AppShell sidebar={<Sidebar sections={sections} />}>…</AppShell>"
    }
  ],
  "accessibility": [
    {
      "feature": "Current page",
      "implementation": "aria-current=page on the active link (prefix or exact matching)",
      "userRequirements": "Pass activeHref on every route"
    },
    {
      "feature": "Mobile navigation",
      "implementation": "Burger opens a focus-trapped Drawer with the same items",
      "userRequirements": "Keep the same item list for both breakpoints"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Nav labels",
      "guidelines": [
        "1-2 nouns",
        "Parallel phrasing"
      ],
      "goodExamples": [
        "Docs",
        "Pricing",
        "Changelog"
      ],
      "badExamples": [
        "Click here for docs"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "SiteFooter",
      "relationship": "Pair header and footer for a complete marketing shell",
      "example": "<SiteHeader … /><main /><SiteFooter … />"
    },
    {
      "component": "Drawer",
      "relationship": "The mobile menu is a Drawer automatically",
      "example": "<SiteHeader … />"
    }
  ],
  "relatedComponents": [
    "SiteFooter",
    "AppShell",
    "Sidebar",
    "Link"
  ]
}
